{
  "links": [
    {
      "href": "https://github.com/example-payments/checkout/pull/219",
      "text": "PR #219: longer session cache TTL"
    }
  ],
  "payload": {
    "custom_details": {
      "change_type": "configuration",
      "cluster": "eks-sre-demo",
      "config_changes": "PAYMENT_SESSION_CACHE_TTL 30s → 60s. No dependency or resource changes.",
      "deployed_by": "ci-bot (merge of PR #219 'longer session cache to cut DB reads')",
      "deployment": "checkout",
      "image": "registry.internal/payments/checkout:v5.2.0",
      "namespace": "payments",
      "platform": "kubernetes",
      "previous_image": "registry.internal/payments/checkout:v5.1.3",
      "resources_changed": "none - memory limit unchanged at 64Mi",
      "rollout": "RollingUpdate, 1/1 replicas updated, healthy for 3h before the incident",
      "service": "checkout"
    },
    "source": "argocd/eks-sre-demo",
    "summary": "Deployed checkout v5.2.0 to eks-sre-demo/payments: payment session cache TTL 30s → 60s (config only)",
    "timestamp": "{{s01_ts1}}"
  },
  "routing_key": "{{change_key_checkout}}"
}

{
  "links": [
    {
      "href": "https://github.com/example-payments/payment-api/pull/482",
      "text": "PR #482: bump iso8583-codec to 4.0.0"
    },
    {
      "href": "https://github.com/example-payments/payment-api/releases/tag/v2.14.0",
      "text": "Release v2.14.0"
    }
  ],
  "payload": {
    "custom_details": {
      "change_type": "dependency upgrade",
      "cluster": "eks-sre-demo",
      "dependency_changes": "iso8583-codec 3.4.2 → 4.0.0 (major). Release notes: card message decoder now pools buffers per acquirer connection.",
      "deployed_by": "ci-bot (merge of PR #482 'bump iso8583-codec to 4.x')",
      "deployment": "payment-api",
      "image": "registry.internal/payments/payment-api:v2.14.0",
      "namespace": "payments",
      "platform": "kubernetes",
      "previous_image": "registry.internal/payments/payment-api:v2.13.4",
      "resources_changed": "none - container still has no memory limit",
      "rollout": "RollingUpdate, 1/1 replicas updated",
      "service": "payment-api"
    },
    "source": "argocd/eks-sre-demo",
    "summary": "Deployed payment-api v2.14.0 to eks-sre-demo/payments: upgrades iso8583-codec 3.4.2 → 4.0.0",
    "timestamp": "{{s02_ts1}}"
  },
  "routing_key": "{{change_key_payment_api}}"
}

{
  "dedup_key": "reinvent/payments/payment-api/probe-latency/{{run_id}}",
  "event_action": "trigger",
  "payload": {
    "class": "probe_latency",
    "component": "payment-api",
    "custom_details": {
      "cluster": "eks-sre-demo",
      "note": "Info-level noise. The Event Orchestration suppresses it, so it never pages anyone.",
      "platform": "kubernetes",
      "service": "payment-api"
    },
    "group": "payments",
    "severity": "info",
    "source": "ip-10-0-12-34.ap-southeast-2.compute.internal",
    "summary": "Kubernetes: liveness probe latency 1.2s on payment-api (threshold 1s)"
  },
  "routing_key": "{{orchestration_routing_key}}"
}

{
  "dedup_key": "reinvent/payments/payment-api/probe-latency/{{run_id}}",
  "event_action": "resolve",
  "payload": {
    "class": "probe_latency",
    "component": "payment-api",
    "custom_details": {
      "cluster": "eks-sre-demo",
      "note": "Info-level noise. The Event Orchestration suppresses it, so it never pages anyone.",
      "platform": "kubernetes",
      "service": "payment-api"
    },
    "group": "payments",
    "severity": "info",
    "source": "ip-10-0-12-34.ap-southeast-2.compute.internal",
    "summary": "Kubernetes: liveness probe latency 1.2s on payment-api (threshold 1s)"
  },
  "routing_key": "{{orchestration_routing_key}}"
}
